#!/usr/bin/env bash
# check-cb00-invariants.sh - eval-only cb00 config-invariant tests (tc-ys2l8.7)
#
# Runs every infrastructure/machines/cb00/test-config-*.nix via `nix eval --file`.
# Eval only: never builds cb00. Triggered by the `cb00-config-invariants` hook
# in nix/flake.nix on cb00 and common/nix/modules/twistcone/ui/ changes.
#
# Exit codes: 0 pass, 1 test failure, 2 configuration error, 3 timeout
set -euo pipefail

readonly TIMEOUT=300 # seconds per test file (cb00 eval is tens of seconds)

if [[ ${1:-} == "--help" ]]; then
  echo "Usage: $0 [file...]   (filenames ignored; always runs all cb00 invariant tests)"
  exit 0
fi

ROOT_DIR="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
dir="$ROOT_DIR/infrastructure/machines/cb00"

shopt -s nullglob
tests=("$dir"/test-config-*.nix)
if [[ ${#tests[@]} -eq 0 ]]; then
  echo "No cb00 config-invariant tests found in $dir" >&2
  exit 2
fi

rc=0
for t in "${tests[@]}"; do
  if out=$(timeout "$TIMEOUT" nix eval --file "$t" 2>&1); then
    echo "PASS: $(basename "$t")"
  else
    code=$?
    if [[ $code -eq 124 ]]; then
      echo "TIMEOUT (${TIMEOUT}s): $(basename "$t")" >&2
      rc=3
    else
      echo "FAIL: $(basename "$t")" >&2
      echo "$out" | head -30 >&2
      [[ $rc -eq 0 ]] && rc=1
    fi
  fi
done
exit $rc
EOF
