// Deterministic in-flight coalescing: while the FIRST fsync is held in flight, N more appends arrive and
// all share exactly ONE further fsync (2 fsyncs for N+1 appends). Every ack is observed only after an
// fsync covering that append's record.
func TestGroupCoalescesWhileFsyncInFlight(t *testing.T) {
	const followers = 7
	l, cf := openCounting(t, t.TempDir(), "group")
	hold := make(chan struct{})
	cf.hold = hold

	var seqMu sync.Mutex
	var next uint64
	var wg sync.WaitGroup
	errs := make(chan error, followers+1)
	appendOne := func() {
		defer wg.Done()
		// Mirror the engine: seq assignment + record write are serial; the durability wait is not.
		seqMu.Lock()
		next++
		_, wait, err := l.AppendDeferred(context.Background(), []core.Event{ev(next, "a")})
		end, _, _, _ := cf.stats()
		seqMu.Unlock()
		if err != nil {
			errs <- err
			return
		}
		if err := wait(); err != nil {
			errs <- err
			return
		}
		if _, syncedTo, _, _ := cf.stats(); syncedTo < end {
			errs <- errors.New("acked before an fsync covered the record")
		}
	}
	wg.Add(1)
	go appendOne() // the leader: blocks inside the held fsync
	waitFor(t, func() bool { _, _, _, syncs := cf.stats(); return syncs == 1 })
	for i := 0; i < followers; i++ {
		wg.Add(1)
		go appendOne()
	}
	waitFor(t, func() bool { _, _, writes, _ := cf.stats(); return writes == followers+1 })
	if _, syncedTo, _, syncs := cf.stats(); syncs != 1 || syncedTo != 0 {
		t.Fatalf("expected exactly one in-flight, uncompleted fsync; syncs=%d syncedTo=%d", syncs, syncedTo)
	}
	close(hold)
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatal(err)
	}
	if _, _, writes, syncs := cf.stats(); syncs != 2 || writes != followers+1 {
		t.Fatalf("%d appends must share exactly 2 fsyncs (in-flight leader + one for the queue); writes=%d syncs=%d", followers+1, writes, syncs)
	}
	got, err := l.Read(context.Background(), 0)
	if err != nil || len(got) != followers+1 {
		t.Fatalf("all %d appends must be readable after ack: %d, %v", followers+1, len(got), err)
	}
	for i, e := range got {
		if e.Seq != uint64(i+1) {
			t.Fatalf("seq must be gapless/ordered, got %d at %d", e.Seq, i)
		}
	}
}

// Crash-style: with the fsync held in flight the append is NOT acked, Read hides the unsynced record (the
// durable frontier, §4.7), and the on-disk image truncated at the last COMPLETED fsync (what survives a
// power loss) holds no acked record. Once the fsync completes the ack happens and the same image holds it.
func TestGroupNoAckedButUnsyncedWindow(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	l, cf := openCounting(t, dir, "group")
	if _, err := l.Append(ctx, []core.Event{ev(1, "a")}); err != nil { // acked + durable baseline
		t.Fatal(err)
	}
	hold := make(chan struct{})
	cf.mu.Lock()
	cf.hold = hold
	cf.mu.Unlock()
	acked := make(chan error, 1)
	go func() {
		_, err := l.Append(ctx, []core.Event{ev(2, "b")})
		acked <- err
	}()
	waitFor(t, func() bool { _, _, _, syncs := cf.stats(); return syncs == 2 }) // fsync for record 2 is in flight

	select {
	case <-acked:
		t.Fatal("Append acked while its fsync was still in flight")
	default:
	}
	if got, _ := l.Read(ctx, 0); len(got) != 1 {
		t.Fatalf("Read must not pass the durable frontier while an fsync is pending; got %d records", len(got))
	}
	if got, _ := l.ReadWritten(ctx, 0); len(got) != 2 {
		t.Fatalf("the writer's own view must include the written record; got %d", len(got))
	}
	// Power-loss image: only bytes covered by a completed fsync survive.
	_, syncedTo, _, _ := cf.stats()
	if n := crashImageEvents(t, dir, syncedTo); n != 1 {
		t.Fatalf("crash image must hold exactly the 1 acked record, got %d", n)
