// crashImageEvents copies the first n bytes of the log into a fresh dir (a power-loss image), reopens it
// through recovery and returns how many events survive.
func crashImageEvents(t *testing.T, dir string, n int64) int {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, "log.jsonl"))
	if err != nil {
		t.Fatal(err)
	}
	if int64(len(b)) < n {
		t.Fatalf("log shorter (%d) than the synced offset %d", len(b), n)
	}
	img := t.TempDir()
	if err := os.WriteFile(filepath.Join(img, "log.jsonl"), b[:n], 0o644); err != nil {
		t.Fatal(err)
	}
	l, err := Open(img, nil)
	if err != nil {
		t.Fatal(err)
	}
	got, err := l.Read(context.Background(), 0)
	if err != nil {
		t.Fatal(err)
	}
