}

// Heavy concurrent workload under -race: every ack is observed only after a covering fsync, there are
// fewer fsyncs than appends (the win over always), seqs stay gapless, and the power-loss image at the
// final synced offset holds every acked record.
func TestGroupConcurrentWritersShareFsyncs(t *testing.T) {
	const writers, per = 16, 10
	dir := t.TempDir()
	l, cf := openCounting(t, dir, "group")
	cf.mu.Lock()
	cf.syncDelay = 2 * time.Millisecond // a realistic non-zero fsync so arrivals overlap an in-flight one
	cf.mu.Unlock()

	var seqMu sync.Mutex
	var next uint64
	var wg sync.WaitGroup
	errs := make(chan error, writers*per)
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < per; i++ {
				seqMu.Lock()
				next++
				_, wait, err := l.AppendDeferred(context.Background(), []core.Event{ev(next, "a")})
				end, _, _, _ := cf.stats()
				seqMu.Unlock()
				if err == nil {
					err = wait()
				}
				if err != nil {
					errs <- err
					return
				}
				if _, syncedTo, _, _ := cf.stats(); syncedTo < end {
					errs <- errors.New("acked before an fsync covered the record")
					return
				}
			}
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatal(err)
	}
	_, syncedTo, writes, syncs := cf.stats()
	if writes != writers*per {
		t.Fatalf("writes=%d want %d", writes, writers*per)
	}
	if syncs >= writes {
		t.Fatalf("group-commit must use fewer fsyncs than appends: syncs=%d appends=%d", syncs, writes)
	}
	t.Logf("appends=%d fsyncs=%d", writes, syncs)
	if n := crashImageEvents(t, dir, syncedTo); n != writers*per {
		t.Fatalf("crash image must hold all %d acked records, got %d", writers*per, n)
	}
}

// A failed fsync latches the log: the waiter gets the error (never an ack), and later appends fail.
func TestGroupFsyncFailureLatches(t *testing.T) {
	ctx := context.Background()
	l, cf := openCounting(t, t.TempDir(), "group")
	cf.mu.Lock()
	cf.failSync = errors.New("disk on fire")
	cf.mu.Unlock()
	if _, err := l.Append(ctx, []core.Event{ev(1, "a")}); !core.IsCode(err, core.ErrIO) {
		t.Fatalf("append must fail with ErrIO when its fsync fails, got %v", err)
	}
	cf.mu.Lock()
	cf.failSync = nil
	cf.mu.Unlock()
	if _, err := l.Append(ctx, []core.Event{ev(2, "b")}); !core.IsCode(err, core.ErrIO) {
		t.Fatalf("a latched log must keep failing appends, got %v", err)
	}
}

// Atomic groups go through the same path: group framing + one shared fsync, readable after the ack.
func TestGroupAtomicAppend(t *testing.T) {
	ctx := context.Background()
	l, cf := openCounting(t, t.TempDir(), "group")
	evs := []core.Event{ev(1, "a"), ev(2, "b")}
	evs[0].Txn, evs[1].Txn = "t1", "t1"
	if _, err := l.AppendAtomic(ctx, evs); err != nil {
		t.Fatal(err)
	}
	if _, _, _, syncs := cf.stats(); syncs != 1 {
		t.Fatalf("an atomic group is ONE fsync, got %d", syncs)
	}
	if got, _ := l.Read(ctx, 0); len(got) != 2 {
		t.Fatalf("group must be readable after ack, got %d", len(got))
	}
}

// Compaction (prefix truncation) works on a group-mode log: it drains pending fsyncs, swaps the handle,
// and later group appends still work.
func TestGroupTruncatePrefix(t *testing.T) {
	ctx := context.Background()
	l, _ := openCounting(t, t.TempDir(), "group")
	for i := uint64(1); i <= 5; i++ {
		if _, err := l.Append(ctx, []core.Event{ev(i, "a")}); err != nil {
			t.Fatal(err)
		}
	}
	if err := l.TruncatePrefix(ctx, 3); err != nil {
		t.Fatal(err)
	}
	if _, err := l.Append(ctx, []core.Event{ev(6, "a")}); err != nil {
		t.Fatal(err)
	}
	got, err := l.Read(ctx, 2)
	if err != nil || len(got) != 4 || got[0].Seq != 3 || got[3].Seq != 6 {
		t.Fatalf("post-compaction read = %+v err %v", got, err)
	}
}
